// Package mapx provides a fluent, chainable wrapper around arbitrary
// map[string]interface{} data.
//
// A Map is created from an existing map with Of, decoded from JSON with
// FromJSON or FromJSONString, built from a struct with FromStruct, or allocated
// empty with New. Every mutating and transforming method returns a Map so calls
// can be chained:
//
//	result := mapx.Of(data).
//		Set("active", true).
//		SetPath("profile.name", "Ada").
//		Only("id", "active", "profile")
//
// Values are coerced on demand by the typed accessors, so JSON numbers, strings
// and booleans can be read without worrying about the concrete Go type.
package mapx

import (
	"sort"
	"time"
)

// Map is a convenience wrapper around map[string]interface{} exposing a fluent
// API for reading and mutating arbitrary JSON-like data.
type Map map[string]interface{}

// New returns an empty, non-nil Map.
func New() Map {
	return Map{}
}

// Of wraps an existing map. The returned Map shares the underlying storage, so
// mutations are visible through both. A nil map yields an empty Map.
func Of(m map[string]interface{}) Map {
	if m == nil {
		return Map{}
	}
	return Map(m)
}

// Raw returns the underlying map.
func (m Map) Raw() map[string]interface{} {
	return map[string]interface{}(m)
}

// Len reports the number of top-level entries.
func (m Map) Len() int {
	return len(m)
}

// IsEmpty reports whether the map has no entries.
func (m Map) IsEmpty() bool {
	return len(m) == 0
}

// Get returns the value stored at key, or nil if absent.
func (m Map) Get(key string) interface{} {
	if m == nil {
		return nil
	}
	return m[key]
}

// GetOk returns the value stored at key and whether it was present.
func (m Map) GetOk(key string) (interface{}, bool) {
	if m == nil {
		return nil, false
	}
	v, ok := m[key]
	return v, ok
}

// Has reports whether key is present (even if its value is nil).
func (m Map) Has(key string) bool {
	_, ok := m[key]
	return ok
}

// Set stores value at key and returns the map for chaining.
func (m Map) Set(key string, value interface{}) Map {
	m[key] = value
	return m
}

// Delete removes key and returns the map for chaining.
func (m Map) Delete(key string) Map {
	if m != nil {
		delete(m, key)
	}
	return m
}

// Keys returns the top-level keys in ascending order.
func (m Map) Keys() []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// Values returns the top-level values ordered by their key.
func (m Map) Values() []interface{} {
	keys := m.Keys()
	out := make([]interface{}, 0, len(keys))
	for _, k := range keys {
		out = append(out, m[k])
	}
	return out
}

// Only returns a new Map containing just the given keys that are present.
func (m Map) Only(keys ...string) Map {
	out := make(Map, len(keys))
	for _, k := range keys {
		if v, ok := m[k]; ok {
			out[k] = v
		}
	}
	return out
}

// Except returns a new Map with the given keys removed.
func (m Map) Except(keys ...string) Map {
	drop := make(map[string]struct{}, len(keys))
	for _, k := range keys {
		drop[k] = struct{}{}
	}
	out := make(Map, len(m))
	for k, v := range m {
		if _, skip := drop[k]; !skip {
			out[k] = v
		}
	}
	return out
}

// Filter returns a new Map with the entries for which fn returns true.
func (m Map) Filter(fn func(key string, value interface{}) bool) Map {
	out := make(Map, len(m))
	for k, v := range m {
		if fn(k, v) {
			out[k] = v
		}
	}
	return out
}

// Reject returns a new Map with the entries for which fn returns false.
func (m Map) Reject(fn func(key string, value interface{}) bool) Map {
	out := make(Map, len(m))
	for k, v := range m {
		if !fn(k, v) {
			out[k] = v
		}
	}
	return out
}

// Transform returns a new Map with every value replaced by fn's result.
func (m Map) Transform(fn func(key string, value interface{}) interface{}) Map {
	out := make(Map, len(m))
	for k, v := range m {
		out[k] = fn(k, v)
	}
	return out
}

// MapKeys returns a new Map whose keys are produced by fn.
func (m Map) MapKeys(fn func(key string, value interface{}) string) Map {
	out := make(Map, len(m))
	for k, v := range m {
		out[fn(k, v)] = v
	}
	return out
}

// Each calls fn for every entry and returns the map for chaining.
func (m Map) Each(fn func(key string, value interface{})) Map {
	for k, v := range m {
		fn(k, v)
	}
	return m
}

// Merge copies the top-level entries of the given maps into m (last wins) and
// returns m for chaining.
func (m Map) Merge(others ...map[string]interface{}) Map {
	for _, other := range others {
		for k, v := range other {
			m[k] = v
		}
	}
	return m
}

// MergeRecursive deep-merges the given maps into m and returns m. Nested maps
// are merged entry by entry; non-map values are overwritten (last wins).
func (m Map) MergeRecursive(others ...map[string]interface{}) Map {
	for _, other := range others {
		mergeInto(m, other)
	}
	return m
}

// Clean returns a new Map without nil values and empty strings, slices and maps.
func (m Map) Clean() Map {
	out := make(Map, len(m))
	for k, v := range m {
		switch x := v.(type) {
		case nil:
			continue
		case string:
			if x == "" {
				continue
			}
		case []interface{}:
			if len(x) == 0 {
				continue
			}
		case map[string]interface{}:
			if len(x) == 0 {
				continue
			}
		}
		out[k] = v
	}
	return out
}

// Clone returns a deep copy of m. Nested maps and slices are copied
// recursively; leaf values are copied by assignment.
func (m Map) Clone() Map {
	out := make(Map, len(m))
	for k, v := range m {
		out[k] = cloneValue(v)
	}
	return out
}

func cloneValue(v interface{}) interface{} {
	switch x := v.(type) {
	case Map:
		return x.Clone()
	case map[string]interface{}:
		return Map(x).Clone()
	case []interface{}:
		out := make([]interface{}, len(x))
		for i := range x {
			out[i] = cloneValue(x[i])
		}
		return out
	default:
		return v
	}
}

func mergeInto(dst, src map[string]interface{}) {
	for k, v := range src {
		if dv, ok := dst[k].(map[string]interface{}); ok {
			if sm, ok := toMap(v); ok {
				mergeInto(dv, sm)
				continue
			}
		}
		dst[k] = v
	}
}

// GetString returns the value at key coerced to a string, or "" if absent or
// not convertible.
func (m Map) GetString(key string) string {
	v, _ := toString(m.Get(key))
	return v
}

// GetInt returns the value at key coerced to an int, or 0 if absent or not
// convertible.
func (m Map) GetInt(key string) int {
	v, _ := toInt64(m.Get(key))
	return int(v)
}

// GetInt64 returns the value at key coerced to an int64, or 0 if absent or not
// convertible.
func (m Map) GetInt64(key string) int64 {
	v, _ := toInt64(m.Get(key))
	return v
}

// GetFloat64 returns the value at key coerced to a float64, or 0 if absent or
// not convertible.
func (m Map) GetFloat64(key string) float64 {
	v, _ := toFloat64(m.Get(key))
	return v
}

// GetBool returns the value at key coerced to a bool, or false if absent or not
// convertible.
func (m Map) GetBool(key string) bool {
	v, _ := toBool(m.Get(key))
	return v
}

// GetMap returns the value at key as a Map. It returns an empty Map if the
// value is absent or not a string-keyed map.
func (m Map) GetMap(key string) Map {
	if mm, ok := toMap(m.Get(key)); ok {
		return mm
	}
	return Map{}
}

// GetSlice returns the value at key as a []interface{}. It returns nil if the
// value is absent or not a slice or array.
func (m Map) GetSlice(key string) []interface{} {
	v, _ := toSlice(m.Get(key))
	return v
}

// GetStrings returns the value at key as a []string, coercing each element. It
// returns nil if the value is absent or not a slice or array.
func (m Map) GetStrings(key string) []string {
	slice, ok := toSlice(m.Get(key))
	if !ok {
		return nil
	}
	out := make([]string, 0, len(slice))
	for _, v := range slice {
		s, _ := toString(v)
		out = append(out, s)
	}
	return out
}

// GetTime returns the value at key parsed as a time.Time. Accepted inputs are
// time.Time, Unix timestamps (numeric), and common string layouts such as
// RFC3339.
func (m Map) GetTime(key string) time.Time {
	v, _ := toTime(m.Get(key))
	return v
}

// GetDuration returns the value at key parsed as a time.Duration. Accepted
// inputs are time.Duration, duration strings ("1h30m") and numeric
// nanosecond counts.
func (m Map) GetDuration(key string) time.Duration {
	v, _ := toDuration(m.Get(key))
	return v
}

// GetOr returns the value at key if present and non-nil, otherwise def.
func (m Map) GetOr(key string, def interface{}) interface{} {
	if v, ok := m.GetOk(key); ok && v != nil {
		return v
	}
	return def
}

// String returns the JSON encoding of the map. It returns "" if the map cannot
// be encoded.
func (m Map) String() string {
	s, err := m.Encode()
	if err != nil {
		return ""
	}
	return s
}

package mapx

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"time"
)

// toString coerces common scalar values to a string.
func toString(v interface{}) (string, bool) {
	switch x := v.(type) {
	case nil:
		return "", false
	case string:
		return x, true
	case []byte:
		return string(x), true
	case json.Number:
		return x.String(), true
	case fmt.Stringer:
		return x.String(), true
	case bool:
		return strconv.FormatBool(x), true
	case int:
		return strconv.Itoa(x), true
	case int8:
		return strconv.FormatInt(int64(x), 10), true
	case int16:
		return strconv.FormatInt(int64(x), 10), true
	case int32:
		return strconv.FormatInt(int64(x), 10), true
	case int64:
		return strconv.FormatInt(x, 10), true
	case uint:
		return strconv.FormatUint(uint64(x), 10), true
	case uint8:
		return strconv.FormatUint(uint64(x), 10), true
	case uint16:
		return strconv.FormatUint(uint64(x), 10), true
	case uint32:
		return strconv.FormatUint(uint64(x), 10), true
	case uint64:
		return strconv.FormatUint(x, 10), true
	case float32:
		return strconv.FormatFloat(float64(x), 'f', -1, 32), true
	case float64:
		return strconv.FormatFloat(x, 'f', -1, 64), true
	default:
		return "", false
	}
}

// toInt64 coerces numbers, numeric strings and booleans to an int64.
func toInt64(v interface{}) (int64, bool) {
	switch x := v.(type) {
	case int:
		return int64(x), true
	case int8:
		return int64(x), true
	case int16:
		return int64(x), true
	case int32:
		return int64(x), true
	case int64:
		return x, true
	case uint:
		return int64(x), true
	case uint8:
		return int64(x), true
	case uint16:
		return int64(x), true
	case uint32:
		return int64(x), true
	case uint64:
		return int64(x), true
	case float32:
		return int64(x), true
	case float64:
		return int64(x), true
	case bool:
		if x {
			return 1, true
		}
		return 0, true
	case json.Number:
		if i, err := x.Int64(); err == nil {
			return i, true
		}
		if f, err := x.Float64(); err == nil {
			return int64(f), true
		}
		return 0, false
	case string:
		s := strings.TrimSpace(x)
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return i, true
		}
		if u, err := strconv.ParseUint(s, 10, 64); err == nil {
			return int64(u), true
		}
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return int64(f), true
		}
		return 0, false
	default:
		return 0, false
	}
}

// toFloat64 coerces numbers, numeric strings and booleans to a float64.
func toFloat64(v interface{}) (float64, bool) {
	switch x := v.(type) {
	case int:
		return float64(x), true
	case int8:
		return float64(x), true
	case int16:
		return float64(x), true
	case int32:
		return float64(x), true
	case int64:
		return float64(x), true
	case uint:
		return float64(x), true
	case uint8:
		return float64(x), true
	case uint16:
		return float64(x), true
	case uint32:
		return float64(x), true
	case uint64:
		return float64(x), true
	case float32:
		return float64(x), true
	case float64:
		return x, true
	case bool:
		if x {
			return 1, true
		}
		return 0, true
	case json.Number:
		f, err := x.Float64()
		return f, err == nil
	case string:
		f, err := strconv.ParseFloat(strings.TrimSpace(x), 64)
		return f, err == nil
	default:
		return 0, false
	}
}

// toBool coerces booleans, "true"/"false" strings and non-zero numbers.
func toBool(v interface{}) (bool, bool) {
	switch x := v.(type) {
	case bool:
		return x, true
	case string:
		b, err := strconv.ParseBool(strings.TrimSpace(x))
		return b, err == nil
	case json.Number:
		f, err := x.Float64()
		return f != 0, err == nil
	default:
		if i, ok := toInt64(v); ok {
			return i != 0, true
		}
		return false, false
	}
}

// toMap coerces any string-keyed map and Map to a Map.
func toMap(v interface{}) (Map, bool) {
	switch x := v.(type) {
	case nil:
		return nil, false
	case Map:
		return x, true
	case map[string]interface{}:
		return Map(x), true
	}

	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Map && rv.Type().Key().Kind() == reflect.String {
		out := make(Map, rv.Len())
		for _, k := range rv.MapKeys() {
			out[k.String()] = rv.MapIndex(k).Interface()
		}
		return out, true
	}
	return nil, false
}

// toSlice coerces any slice or array to a []interface{}.
func toSlice(v interface{}) ([]interface{}, bool) {
	if s, ok := v.([]interface{}); ok {
		return s, true
	}
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
		out := make([]interface{}, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = rv.Index(i).Interface()
		}
		return out, true
	}
	return nil, false
}

// toTime parses time.Time, Unix timestamps and common string layouts.
func toTime(v interface{}) (time.Time, bool) {
	switch x := v.(type) {
	case time.Time:
		return x, true
	case *time.Time:
		if x == nil {
			return time.Time{}, false
		}
		return *x, true
	case json.Number:
		if i, err := x.Int64(); err == nil {
			return time.Unix(i, 0), true
		}
		return time.Time{}, false
	case int64:
		return time.Unix(x, 0), true
	case int:
		return time.Unix(int64(x), 0), true
	case float64:
		return time.Unix(int64(x), 0), true
	case string:
		s := strings.TrimSpace(x)
		for _, layout := range []string{
			time.RFC3339Nano,
			time.RFC3339,
			"2006-01-02 15:04:05",
			"2006-01-02",
			time.RFC1123,
		} {
			if t, err := time.Parse(layout, s); err == nil {
				return t, true
			}
		}
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return time.Unix(i, 0), true
		}
		return time.Time{}, false
	default:
		return time.Time{}, false
	}
}

// toDuration parses time.Duration, duration strings and numeric nanoseconds.
func toDuration(v interface{}) (time.Duration, bool) {
	switch x := v.(type) {
	case time.Duration:
		return x, true
	case string:
		s := strings.TrimSpace(x)
		if d, err := time.ParseDuration(s); err == nil {
			return d, true
		}
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return time.Duration(i), true
		}
		return 0, false
	default:
		if i, ok := toInt64(v); ok {
			return time.Duration(i), true
		}
		return 0, false
	}
}

package mapx

import (
	"strconv"
	"strings"
	"time"
)

// splitPath breaks a path into segments. Both "a.b.c" and "a[b].c" forms are
// supported; empty segments are ignored.
func splitPath(path string) []string {
	path = strings.TrimSpace(path)
	if path == "" {
		return nil
	}
	replacer := strings.NewReplacer("[", ".", "]", ".")
	raw := strings.Split(replacer.Replace(path), ".")
	out := make([]string, 0, len(raw))
	for _, part := range raw {
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

// Path returns the value at a dotted path. Path segments traverse nested maps
// and, for slices, numeric indices, e.g. "users[0].name" or "users.0.name".
// It returns nil if the path does not resolve.
func (m Map) Path(path string) interface{} {
	parts := splitPath(path)
	if len(parts) == 0 {
		return nil
	}
	var cur interface{} = map[string]interface{}(m)
	for _, part := range parts {
		switch node := cur.(type) {
		case Map:
			cur = node[part]
		case map[string]interface{}:
			cur = node[part]
		case []interface{}:
			idx, err := strconv.Atoi(part)
			if err != nil || idx < 0 || idx >= len(node) {
				return nil
			}
			cur = node[idx]
		default:
			return nil
		}
	}
	return cur
}

// HasPath reports whether a dotted path resolves to a value, even a nil one.
func (m Map) HasPath(path string) bool {
	parts := splitPath(path)
	if len(parts) == 0 {
		return false
	}
	var cur interface{} = map[string]interface{}(m)
	for _, part := range parts {
		switch node := cur.(type) {
		case Map:
			v, ok := node[part]
			if !ok {
				return false
			}
			cur = v
		case map[string]interface{}:
			v, ok := node[part]
			if !ok {
				return false
			}
			cur = v
		case []interface{}:
			idx, err := strconv.Atoi(part)
			if err != nil || idx < 0 || idx >= len(node) {
				return false
			}
			cur = node[idx]
		default:
			return false
		}
	}
	return true
}

// SetPath stores value at a dotted path, creating intermediate maps as needed,
// and returns the map for chaining.
func (m Map) SetPath(path string, value interface{}) Map {
	parts := splitPath(path)
	if len(parts) == 0 {
		return m
	}
	cur := map[string]interface{}(m)
	for i, part := range parts {
		if i == len(parts)-1 {
			cur[part] = value
			return m
		}
		next, ok := cur[part].(map[string]interface{})
		if !ok {
			if existing, ok := toMap(cur[part]); ok {
				next = map[string]interface{}(existing)
			} else {
				next = map[string]interface{}{}
			}
			cur[part] = next
		}
		cur = next
	}
	return m
}

// DeletePath removes the value at a dotted path and returns the map for
// chaining. Only map segments can be removed; slice elements are left intact.
func (m Map) DeletePath(path string) Map {
	parts := splitPath(path)
	if len(parts) == 0 {
		return m
	}
	var cur interface{} = map[string]interface{}(m)
	for _, part := range parts[:len(parts)-1] {
		switch node := cur.(type) {
		case Map:
			cur = node[part]
		case map[string]interface{}:
			cur = node[part]
		case []interface{}:
			idx, err := strconv.Atoi(part)
			if err != nil || idx < 0 || idx >= len(node) {
				return m
			}
			cur = node[idx]
		default:
			return m
		}
	}
	last := parts[len(parts)-1]
	switch node := cur.(type) {
	case Map:
		delete(node, last)
	case map[string]interface{}:
		delete(node, last)
	}
	return m
}

// PathString returns the value at path coerced to a string.
