func TestMerge(t *testing.T) {
	m := Of(map[string]interface{}{
		"a": 1,
		"nested": map[string]interface{}{
			"x": 1,
		},
	})
	other := map[string]interface{}{
		"b": 2,
		"nested": map[string]interface{}{
			"y": 2,
